    receive() external payable {}

    function run(address a, address b) public {
        require(a != address(0) && b != address(0) && a != b);

        c.setOwner(a); if (__ESBMC_reverted()) return;
        address afterA = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.setOwner(b); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        address afterB = c.owner(); if (__ESBMC_reverted()) return;

        assert(!reverted ? afterB == b : afterB == a);
    }
}

